// onchain-billing-reconcile — Plan run (task 015-18, data-model.md §4.6.5, deployment.md §10.8).
//
// ONE pass mints the run's ULID, freezes `startedAt`/`nowMs`, and computes the horizon the scan's
// own WHERE clause reads (`reserved_at < horizon`). Nothing downstream re-derives any of it: every
// batch in the drain loop below binds the SAME horizon and the SAME nowMs, so the `retention_runs`
// row can name the period the run actually covered, not a period that drifted mid-run.
//
// **`ThresholdMs` below the 120 000 ms floor is refused, not clamped** (R-14.2, "Отвергнутая
// настройка"). A lower value would return the reserve of a request that is still executing — money
// for work not yet done, not a period nobody chose. There is no second query node in this graph to
// route around; the refusal is pulled by forcing `effectiveBatchSize` to 0 so `Refund expired`'s own
// `LIMIT` matches zero rows on the one pass it still makes. `batchSize` (the DECLARED setting)
// stays in the run row's `detail_json` untouched, so a reader sees what was CONFIGURED, not what
// the guard forced.
//
// **The accumulator lives in workflow static data, namespaced by `$execution.id`.** A manual
// IF-back-edge loop (not the native Loop node) re-executes `Tally` once per batch, and n8n's own
// `$('Tally').all()` returns only the LAST run inside a loop — the documented cross-iteration
// gotcha (n8n-code-javascript skill, "Cross-Iteration Data Accumulation"). Namespacing by execution
// id, rather than one shared key, also keeps two overlapping runs — the exact case
// `FOR UPDATE SKIP LOCKED` below is written to tolerate — from corrupting each other's running
// totals; `Row client_usage.reconcile_expired` deletes this run's own key once it has read it.
const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function ulid(ms) {
  let time = '';
  let rest = ms;
  for (let i = 0; i < 10; i += 1) { time = B32[rest % 32] + time; rest = Math.floor(rest / 32); }
  let rand = '';
  for (let i = 0; i < 16; i += 1) rand += B32[Math.floor(Math.random() * 32)];
  return time + rand;
}

const params = $('Set Parameters').first().json;
const startedAt = Date.now();

const FLOOR_MS = 120000; // R-14.2 — twice the largest declared deadlineMs (data-model.md §4.6.5)
const thresholdRaw = params.ThresholdMs;
const thresholdMs = typeof thresholdRaw === 'number' && Number.isFinite(thresholdRaw) ? thresholdRaw : NaN;
const valid = Number.isFinite(thresholdMs) && thresholdMs >= FLOOR_MS;
// A non-finite/garbage setting still needs a period the CHECK(period_to > period_from) constraint
// accepts — refuse the run (below) but never fail to compute a coordinate for its own row.
const safeThresholdMs = Number.isFinite(thresholdMs) ? thresholdMs : 0;

const horizon = startedAt - safeThresholdMs; // period_to — the same value the WHERE clause reads
const batchSize = typeof params.BatchSize === 'number' ? params.BatchSize : 500;
const maxBatches = typeof params.MaxBatches === 'number' ? params.MaxBatches : 20;
const effectiveBatchSize = valid ? batchSize : 0;

const reasons = valid
  ? []
  : [`ThresholdMs ${JSON.stringify(thresholdRaw)} is below the floor of ${FLOOR_MS} ms — a lower ` +
     'value would return the reserve of a request that is still executing (R-14.2)'];

const paramsB64 = Buffer.from(JSON.stringify({
  horizon,
  batchSize: effectiveBatchSize,
  nowMs: startedAt,
})).toString('base64');

const execId = $execution.id;
const staticData = $getWorkflowStaticData('global');
staticData[execId] = { rowsAffected: 0, profilesCredited: 0, batches: 0, batchExhausted: false };

return [{ json: {
  id: ulid(startedAt),
  execId,
  startedAt,
  thresholdMs: safeThresholdMs,
  thresholdRaw,
  batchSize,
  effectiveBatchSize,
  maxBatches,
  horizon,
  periodFrom: 0,
  periodTo: horizon,
  valid,
  reasons,
  paramsB64,
} }];

// onchain-billing-reconcile — Tally (task 015-18, MINOR-10 round 2: drain to empty, capped batches).
//
// Runs once per pass through `Refund expired`. Folds THIS batch's own result into the
// execution-scoped accumulator `Plan run` seeded in static data (see that node's own comment for
// why static data, namespaced by execution id, is the fix for the cross-iteration gotcha).
//
// **`full` drives the loop; `batchExhausted` drives the alert, and they are not the same test.** A
// batch that comes back short of `BatchSize` means the table is drained — done, not backlog. A
// batch that comes back FULL right as `MaxBatches` is reached means real backlog remains past the
// cap: that is what `Check backlog` must throw on, and a run that happens to finish exactly ON its
// last allowed batch is not conflated with one that is still hungry.
const plan = $('Plan run').first().json;
const execId = plan.execId;
const staticData = $getWorkflowStaticData('global');
const acc = staticData[execId];

const result = $input.first().json;
const rowsAffectedThisBatch = Number(result?.rows_affected ?? 0);
const profilesCreditedThisBatch = Number(result?.profiles_credited ?? 0);

acc.batches += 1;
acc.rowsAffected += Number.isFinite(rowsAffectedThisBatch) ? rowsAffectedThisBatch : 0;
acc.profilesCredited += Number.isFinite(profilesCreditedThisBatch) ? profilesCreditedThisBatch : 0;

const full = rowsAffectedThisBatch === plan.effectiveBatchSize && plan.effectiveBatchSize > 0;
acc.batchExhausted = full && acc.batches >= plan.maxBatches;
const continueLoop = full && !acc.batchExhausted;

return [{ json: {
  rowsAffectedThisBatch,
  full,
  continueLoop,
  batches: acc.batches,
  rowsAffectedTotal: acc.rowsAffected,
  profilesCreditedTotal: acc.profilesCredited,
  batchExhausted: acc.batchExhausted,
} }];

// onchain-billing-reconcile — the `retention_runs` row (task 015-18; MINOR-8 round 1: period from
// the threshold; MINOR-10 round 2: batch size and overflow named in `detail_json`; R-14.3: a run
// with zero findings still writes a row).
//
// `outcome` is 'failed' ONLY for a rejected `ThresholdMs` — the vocabulary is closed to two values
// (data-model.md §4.5.9) and a run that closed every stuck row it found is not a failure for having
// also hit `MaxBatches`; `batchExhausted` in `detail_json` is the observable for that instead.
const plan = $('Plan run').first().json;
const execId = plan.execId;
const staticData = $getWorkflowStaticData('global');
const acc = staticData[execId] || { rowsAffected: 0, profilesCredited: 0, batches: 0, batchExhausted: false };
delete staticData[execId]; // one run, one row — nothing left in static data for a later execution to trip over

const detail = {
  thresholdMs: plan.thresholdMs,
  thresholdRaw: plan.thresholdRaw,
  batchSize: plan.batchSize,
  maxBatches: plan.maxBatches,
  batches: acc.batches,
  batchExhausted: acc.batchExhausted,
  profilesCredited: acc.profilesCredited,
  periodFrom: plan.periodFrom,
  periodTo: plan.periodTo,
};
if (!plan.valid) detail.rejected = { thresholdRaw: plan.thresholdRaw, reasons: plan.reasons };

const row = {
  id: plan.id,
  job: 'client_usage.reconcile_expired',
  // No schema prefix — data-model.md:2185's own literal 'client_usage'. The three onchain-retention
  // jobs write a schema-qualified target_table; the mismatch is recorded (task 015-18), not
  // corrected here — fixing someone else's rows is a separate decision.
  target_table: 'client_usage',
  period_from: plan.periodFrom,
  period_to: plan.periodTo,
  rows_affected: acc.rowsAffected,
  started_at: plan.startedAt,
  finished_at: Date.now(),
  outcome: plan.valid ? 'ok' : 'failed',
  detail_json: JSON.stringify(detail),
};

return [{ json: {
  row_b64: Buffer.from(JSON.stringify([row])).toString('base64'),
  batchExhausted: acc.batchExhausted,
  rejected: !plan.valid,
  reasons: plan.reasons,
  thresholdRaw: plan.thresholdRaw,
} }];

// onchain-billing-reconcile — the terminal gate (L-2: a diagnostic nobody reads is not a diagnostic).
//
// Reads the signals `Row client_usage.reconcile_expired` computed for the row `Write run` just
// persisted, and throws on either: a `ThresholdMs` below the 120 000 ms floor was refused (R-14.2,
// "Отвергнутая настройка"), or `MaxBatches` was reached with a still-full last batch, meaning
// backlog remains past the cap (MINOR-10 round 2). Chained AFTER `Write run`, not fanned out beside
// it (CLAUDE.n8n.md — "after X" needs an edge, not a canvas position); every upstream node in this
// chain carries `alwaysOutputData: true` so an empty result cannot silently skip this gate.
const row = $('Row client_usage.reconcile_expired').first().json;

if (row.rejected) {
  throw new Error(
    `onchain-billing-reconcile refused ThresholdMs=${JSON.stringify(row.thresholdRaw)} — ` +
      `${(row.reasons || []).join('; ')}. The setting lives in the "Set Parameters" node ` +
      '(deployment.md §10.8).',
  );
}

if (row.batchExhausted) {
  throw new Error(
    'onchain-billing-reconcile hit MaxBatches with a still-full last batch — backlog remains in ' +
      'onchain.client_usage past the reconciliation horizon. Raise MaxBatches/BatchSize in the ' +
      '"Set Parameters" node, or investigate why reserved rows are accumulating faster than this ' +
      'job drains them.',
  );
}

return [{ json: { ok: true } }];
